begin;
create table public.care_coordinators (id uuid primary key default gen_random_uuid(), profile_id uuid not null unique references public.profiles(id) on delete restrict, status public.coordinator_status not null default 'active', max_active_cases integer check(max_active_cases is null or max_active_cases>=0), created_at timestamptz not null default statement_timestamp());
alter table public.patients add constraint patients_primary_coordinator_fk foreign key(primary_coordinator_id) references public.care_coordinators(id) on delete set null;
alter table public.care_requests add constraint care_requests_coordinator_fk foreign key(coordinator_id) references public.care_coordinators(id) on delete set null;
create table public.follow_ups (id uuid primary key default gen_random_uuid(), encounter_id uuid not null references public.care_encounters(id) on delete restrict, patient_id uuid not null references public.patients(id) on delete restrict, assigned_to_profile_id uuid references public.profiles(id) on delete restrict, follow_up_type public.follow_up_type not null, due_at timestamptz, instructions text, status public.follow_up_status not null default 'pending', completed_at timestamptz, check((status='completed')=(completed_at is not null)));
create table public.monitoring_alerts (id uuid primary key default gen_random_uuid(), patient_id uuid not null references public.patients(id) on delete restrict, vital_reading_id uuid references public.vital_readings(id) on delete restrict, alert_type text not null, severity public.alert_severity not null, message text not null, status public.alert_status not null default 'open', reviewed_by_profile_id uuid references public.profiles(id) on delete restrict, created_at timestamptz not null default statement_timestamp(), resolved_at timestamptz, check((status='resolved')=(resolved_at is not null)));
create index monitoring_alerts_patient_status_idx on public.monitoring_alerts(patient_id,status,created_at desc);
create index monitoring_alerts_open_idx on public.monitoring_alerts(patient_id,created_at desc) where status='open';
create table public.notifications (id uuid primary key default gen_random_uuid(), recipient_profile_id uuid not null references public.profiles(id) on delete restrict, patient_id uuid references public.patients(id) on delete restrict, type public.notification_type not null, channel public.notification_channel not null, title text not null, body text not null, status public.notification_status not null default 'queued', scheduled_at timestamptz, sent_at timestamptz, read_at timestamptz);
create index notifications_recipient_status_idx on public.notifications(recipient_profile_id,status,scheduled_at);
commit;
